import os,re
CSS="""
:root{--ink:#14122b;--muted:#4b5065;--brand:#4b3fd6;--brand-d:#3324ad;--soft:#f0efff;--line:#e3e4ef;--bg:#f6f6fb;--card:#fff;--r:20px;--night:#15123a;
--sans:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;--serif:"Iowan Old Style","Palatino Linotype",Palatino,"Book Antiqua",Georgia,serif}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:var(--sans);color:var(--ink);background:var(--bg);line-height:1.65;font-size:1.0625rem}
h1,h2,h3{font-family:var(--serif);line-height:1.18;letter-spacing:-.015em;margin:0 0 .5em}h1{font-size:clamp(2.2rem,5vw,3.5rem)}h2{font-size:1.8rem}h3{font-size:1.25rem}
a{color:var(--brand-d)}.skip{position:absolute;left:-999px;top:8px;background:#fff;color:var(--ink);padding:10px 16px;border-radius:8px;z-index:10}.skip:focus{left:12px}
.vh{position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
:focus-visible{outline:3px solid #ffb020;outline-offset:3px;border-radius:6px}
.site{position:relative;overflow:hidden;color:#fff;background-color:var(--night);background-image:radial-gradient(600px 320px at 8% -5%,rgba(255,106,61,.38),transparent 62%),radial-gradient(760px 420px at 92% 0%,rgba(124,92,255,.6),transparent 62%),radial-gradient(520px 300px at 50% 130%,rgba(0,190,200,.32),transparent 60%),linear-gradient(160deg,#15123a,#241b78)}
.site::after{content:"";position:absolute;inset:0;background-image:radial-gradient(rgba(255,255,255,.09) 1px,transparent 1px);background-size:22px 22px;pointer-events:none;mask-image:linear-gradient(#000,transparent)}
.bar{position:relative;z-index:1;max-width:1200px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:18px 24px;flex-wrap:wrap}.bar a{color:#fff;text-decoration:none;font-weight:600}
.brand{display:flex;gap:12px;align-items:center;line-height:1.1}.brand b{font-size:1.25rem;letter-spacing:.04em}.brand small{display:block;font-weight:500;font-size:.78rem;color:#dedbff}
.bar ul{list-style:none;display:flex;gap:22px;margin:0;padding:0}.bar ul a{color:#ecebff}.bar ul a:hover{text-decoration:underline}
.hero{position:relative;z-index:1;max-width:860px;margin:0 auto;padding:44px 24px 96px;text-align:center}.hero p{font-size:1.18rem;color:#efeeff;margin:0 auto 26px;max-width:640px}
.hero .eyebrow{color:#ffd9bf}.hero-ico{width:76px;height:76px;margin:0 auto 18px;border-radius:22px;display:grid;place-items:center;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.28);box-shadow:0 10px 30px rgba(0,0,0,.25)}.hero-ico svg{width:40px;height:40px}
.ico svg,.hero-ico svg{fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.ico{flex:none;width:52px;height:52px;border-radius:16px;display:grid;place-items:center;color:#fff;background:linear-gradient(135deg,var(--c1),var(--c2));box-shadow:0 8px 18px -6px var(--c2)}.ico svg{width:26px;height:26px}
.cat-business{--c1:#ff8a3d;--c2:#e8366b}.cat-image{--c1:#1fb89c;--c2:#1a7fd0}.cat-docs{--c1:#ff5e5e;--c2:#b8307f}.cat-media{--c1:#9a6bff;--c2:#4b3fd6}.cat-writing{--c1:#3fa2ff;--c2:#4b3fd6}.cat-security{--c1:#2bb673;--c2:#0d7a5f}
.layout{position:relative;z-index:2;max-width:1200px;margin:-56px auto 0;padding:0 24px 48px;display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:28px;align-items:start}
@media(max-width:1000px){.layout{grid-template-columns:minmax(0,1fr)}}
section.card,aside.card{position:relative;background:var(--card);border:1px solid var(--line);border-radius:var(--r);box-shadow:0 1px 2px rgba(20,18,43,.04),0 18px 50px -20px rgba(36,27,120,.25);padding:clamp(22px,4vw,44px);margin:0 0 28px;overflow:hidden}
section.card::before,aside.card::before{content:"";position:absolute;left:0;right:0;top:0;height:4px;background:linear-gradient(90deg,#ff8a3d,#e8366b,#7c5cff,#1fb89c)}
.eyebrow{text-transform:uppercase;letter-spacing:.12em;font-size:.8rem;font-weight:700;color:var(--brand-d);margin:0 0 6px}.lead{color:var(--muted);max-width:680px}
label,legend{display:block;font-weight:600;margin:14px 0 6px;font-size:.95rem}fieldset{border:1px solid var(--line);border-radius:14px;padding:6px 18px 18px;margin:0}
input,textarea,select{width:100%;padding:12px 14px;border:1.5px solid #858ba3;border-radius:12px;font:inherit;background:#fff;color:var(--ink);transition:border-color .2s,box-shadow .2s}textarea{min-height:110px}
input:focus,textarea:focus,select:focus{border-color:var(--brand);box-shadow:0 0 0 4px rgba(75,63,214,.15)}input[type=range]{padding:0;border:0;box-shadow:none;accent-color:var(--brand)}input[type=color]{height:48px;padding:4px}
.check{display:flex;gap:10px;align-items:center;font-weight:500}.check input{width:auto;accent-color:var(--brand)}
button,.btn{display:inline-flex;align-items:center;gap:8px;background:linear-gradient(135deg,#5a4ce8,#3324ad);color:#fff;border:0;border-radius:999px;padding:12px 22px;font:inherit;font-weight:650;cursor:pointer;text-decoration:none;margin:14px 10px 0 0;box-shadow:0 8px 20px -10px #3324ad;transition:transform .2s,box-shadow .2s,background .2s}
button:hover,.btn:hover{transform:translateY(-1px);box-shadow:0 12px 24px -10px #3324ad}button:disabled{opacity:.55;cursor:not-allowed;transform:none}
.btn.alt,button.alt{background:var(--soft);color:var(--brand-d);box-shadow:none}.btn.alt:hover,button.alt:hover{background:#e2e0ff}.btn.light{background:#fff;color:var(--brand-d)}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(230px,100%),1fr));gap:20px}.out{background:#f7f8fc;border:1px solid var(--line);border-radius:14px;padding:20px;white-space:pre-wrap;margin-top:18px}
.stat{background:#f7f8fc;border:1px solid var(--line);border-radius:14px;padding:14px 16px}.stat b{display:block;font-size:1.6rem;font-family:var(--serif);color:var(--brand-d)}
.price{border:1px solid var(--line);border-radius:16px;padding:26px;background:#fff}.price.feat{background:linear-gradient(160deg,#f3f1ff,#fff2ec);border-color:#d6d1fb}.big{font-family:var(--serif);font-size:2.2rem;font-weight:700;color:var(--brand-d)}
.tiles{list-style:none;padding:0;margin:0;display:grid;grid-template-columns:repeat(auto-fill,minmax(min(250px,100%),1fr));gap:18px}
.tile{position:relative;display:flex;flex-direction:column;gap:10px;border:1px solid var(--line);border-radius:18px;padding:22px;background:linear-gradient(180deg,#fff,#fbfbff);transition:transform .25s,box-shadow .25s,border-color .25s}
.tile:hover,.tile:focus-within{transform:translateY(-4px);box-shadow:0 18px 40px -18px rgba(36,27,120,.35);border-color:#cfcaf7}.tile h3{margin:6px 0 0}.tile p{margin:0;color:var(--muted);font-size:.97rem}
.tile a{text-decoration:none;color:var(--ink)}.tile a::after{content:"";position:absolute;inset:0;border-radius:18px}.tile .tag{font-size:.78rem;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}
.featured{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(220px,100%),1fr));gap:18px;list-style:none;padding:0;margin:0}
.feat-card{position:relative;border-radius:20px;padding:24px;color:#fff;background:radial-gradient(260px 160px at 100% 0%,var(--c1),transparent 70%),linear-gradient(160deg,#1d1752,#2b2190);overflow:hidden;transition:transform .25s}
.feat-card:hover,.feat-card:focus-within{transform:translateY(-4px)}.feat-card h3{margin:14px 0 6px}.feat-card p{margin:0;color:#e6e4ff}.feat-card a{color:#fff;text-decoration:none}.feat-card a::after{content:"";position:absolute;inset:0}
.chips{display:flex;flex-wrap:wrap;gap:10px;margin:14px 0 20px}.chip{margin:0;background:#fff;color:var(--ink);border:1.5px solid var(--line);box-shadow:none;padding:8px 16px}.chip[aria-pressed=true]{background:var(--brand-d);color:#fff;border-color:var(--brand-d)}
.search{max-width:560px;margin:0 auto}.search input{border-radius:999px;padding:16px 22px;border:0;box-shadow:0 12px 30px rgba(0,0,0,.25)}.search label{color:#fff}
.rail{position:sticky;top:20px}.ad-label{display:block;font-size:.75rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin-bottom:6px;text-align:center}
.ad-slot{width:300px;height:600px;margin:0 auto;border:1px dashed #c9cbe0;border-radius:14px;background:repeating-linear-gradient(45deg,#f3f3f9,#f3f3f9 10px,#f8f8fc 10px,#f8f8fc 20px);overflow:hidden}
@media(max-width:1000px){.rail{position:static}.ad-slot{width:100%;max-width:728px;height:100px}}
footer{text-align:center;padding:40px 24px;color:var(--muted);font-size:.95rem}footer .brand{justify-content:center;color:var(--ink);margin-bottom:8px}footer .brand small{color:var(--muted)}
table{width:100%;border-collapse:collapse}#items{table-layout:fixed}#items th:nth-child(1){width:44%}#items th:nth-child(4){width:52px}#items td input{min-width:0;padding:8px}#items td button{padding:8px 10px;margin:0}#doc table{table-layout:fixed;word-break:break-word}main,section.card{min-width:0}td,th{padding:8px 6px;border-bottom:1px solid var(--line);text-align:left}
.swatches{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(120px,100%),1fr));gap:12px;margin-top:16px}.swatch{margin:0;height:120px;border-radius:16px;display:flex;align-items:flex-end;justify-content:flex-start;padding:12px;font-weight:700;box-shadow:inset 0 0 0 1px rgba(0,0,0,.08)}
@media (prefers-reduced-motion:no-preference){section.card,.hero>*{animation:rise .6s ease both}section.card:nth-of-type(2){animation-delay:.08s}section.card:nth-of-type(3){animation-delay:.16s}@keyframes rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{transition:none!important;animation:none!important}}.crumbs ol{list-style:none;display:flex;flex-wrap:wrap;justify-content:center;gap:6px;margin:0 0 14px;padding:0;font-size:.9rem;color:#e6e4ff}.crumbs li+li::before{content:"›";margin-right:6px;color:#c9c5ff}.crumbs a{color:#fff}.crumbs [aria-current]{color:#ffd9bf}
.backlink{margin:22px 0 0;font-weight:600}.flinks{list-style:none;display:flex;flex-wrap:wrap;justify-content:center;gap:6px 18px;padding:0;margin:8px 0}.prose h2{margin-top:1.2em}.prose h2:first-child{margin-top:0}
.ad-inline{margin:0 0 28px}.ad-in-slot{height:120px;border:1px dashed #c9cbe0;border-radius:14px;background:repeating-linear-gradient(45deg,#f3f3f9,#f3f3f9 10px,#f8f8fc 10px,#f8f8fc 20px);overflow:hidden}
.thanks{position:relative;z-index:3;max-width:1200px;margin:16px auto 0;padding:0 24px}.thanks div{display:flex;align-items:center;justify-content:space-between;gap:12px;background:#e9fbf3;border:1px solid #9be3c4;color:#0b4d34;border-radius:14px;padding:10px 12px 10px 18px;font-weight:600}.thanks button{margin:0;background:#fff;color:#0b4d34;box-shadow:none;padding:6px 12px}
/* reserved right gutter so the fixed helper button never overlaps content */
:root{--gut:64px}.bar,.layout,.thanks{padding-right:clamp(24px,calc(var(--gut) - (100vw - 1200px)/2),var(--gut))}.hero{padding-right:clamp(24px,calc(var(--gut) - (100vw - 860px)/2),var(--gut))}footer{padding-right:var(--gut)}
.gwb-fab{position:fixed;right:10px;bottom:10px;z-index:50;margin:0;width:48px;height:48px;padding:0;justify-content:center;border-radius:50%;box-shadow:0 8px 20px -6px rgba(20,18,43,.55)}.gwb-fab svg{width:22px;height:22px;fill:none;stroke:#fff;stroke-width:2;stroke-linejoin:round}.fab-txt{display:none}
.gwb-top{position:fixed;right:12px;bottom:66px;z-index:49;margin:0;width:44px;height:44px;padding:0;justify-content:center;border-radius:50%;background:#fff;color:var(--brand-d);border:1.5px solid #c9c5f0;box-shadow:0 6px 16px -6px rgba(20,18,43,.45)}.gwb-top[hidden]{display:none}.gwb-top svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}.gwb-top:hover{background:var(--soft)}
#main:focus{outline:none}
@media(min-width:768px){:root{--gut:170px}.gwb-fab{width:auto;height:50px;padding:0 20px 0 16px;border-radius:999px;gap:8px;right:14px;bottom:14px;font-size:1rem;background:linear-gradient(135deg,#b23a10,#a8104a 50%,#4b2fc0);font-weight:700;box-shadow:0 10px 26px -8px rgba(232,54,107,.6),0 4px 10px rgba(20,18,43,.25)}.fab-txt{display:inline}.gwb-panel{bottom:76px;right:14px}.gwb-top{right:17px;bottom:74px}}
@media (prefers-reduced-motion:no-preference){.gwb-fab.pulse{animation:gwbpulse 1.6s ease-out 2}@keyframes gwbpulse{0%{box-shadow:0 0 0 0 rgba(232,54,107,.55)}100%{box-shadow:0 0 0 18px rgba(232,54,107,0)}}}
.gwb-panel{position:fixed;right:10px;bottom:66px;z-index:51;width:min(320px,calc(100vw - 20px));max-height:60vh;display:flex;flex-direction:column;background:#fff;color:var(--ink);border:1px solid #d6d8e6;border-radius:16px;box-shadow:0 20px 50px -12px rgba(20,18,43,.45);overflow:hidden;font-size:.95rem}
.gwb-panel[hidden]{display:none}.gwb-head{display:flex;justify-content:space-between;align-items:center;padding:10px 12px 8px 16px;border-bottom:1px solid var(--line)}.gwb-head h2{font-size:1.1rem;margin:0}
.gwb-x{margin:0;width:36px;height:36px;padding:0;justify-content:center;font-size:1.4rem;line-height:1;background:var(--soft);color:var(--ink);box-shadow:none}.gwb-body{padding:12px 16px 14px;overflow:auto}
.gwb-body .hrow input{padding:9px 12px}.gwb-body .hrow button{padding:9px 14px}.hchips{margin:10px 0 4px!important}.hres{margin-top:10px;padding:12px!important}.hres .ico{width:40px;height:40px;border-radius:12px}.hres .ico svg{width:20px;height:20px}
.hopen{margin:10px 0 6px!important;padding:10px 16px!important}.hres .hsmall{margin:4px 0 0}
@media(max-width:640px){.gwb-panel{left:0;right:0;bottom:0;width:100%;max-height:60vh;border-radius:16px 16px 0 0}}
@media (prefers-reduced-motion:no-preference){.gwb-panel{animation:rise .2s ease both}}
.hrow{display:flex;gap:8px}.hrow input{border-radius:999px}.hrow button{margin:0;flex:none}
.hchips{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.hchips .chip{font-size:.85rem;padding:6px 12px}
.hmsg.you{margin:12px 0 8px auto;max-width:90%;width:fit-content;background:var(--brand-d);color:#fff;padding:8px 14px;border-radius:16px 16px 4px 16px;font-size:.95rem}
.hres{background:#f7f8fc;border:1px solid var(--line);border-radius:16px 16px 16px 4px;padding:16px;font-size:.95rem}
.hsay{margin:0 0 12px}.hbest{display:flex;gap:12px;align-items:center}.hname{margin:0;font-weight:700;font-family:var(--serif);font-size:1.1rem}.hsmall{margin:0;color:var(--muted);font-size:.88rem}
.hopen{width:100%;justify-content:center;margin:14px 0 4px;padding:14px 18px}.hsub{margin:12px 0 4px;font-weight:700;font-size:.8rem;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)}
.htips,.hrel{margin:0;padding-left:20px}.htips li,.hrel li{margin:2px 0}
@media (prefers-reduced-motion:no-preference){.hres,.hmsg{animation:rise .35s ease both}}
@media print{.site,.noprint,footer,#pricing,.rail{display:none!important}.layout{display:block;margin:0}body{background:#fff}section.card{box-shadow:none;border:0}section.card::before{display:none}}"""
LOGO='<svg width="40" height="40" viewBox="0 0 40 40" aria-hidden="true" focusable="false"><defs><linearGradient id="gwbg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#ffa24c"/><stop offset=".55" stop-color="#e8366b"/><stop offset="1" stop-color="#7c5cff"/></linearGradient></defs><rect width="40" height="40" rx="12" fill="url(#gwbg)"/><circle cx="20" cy="20" r="11" fill="none" stroke="#fff" stroke-width="2.4"/><ellipse cx="20" cy="20" rx="4.8" ry="11" fill="none" stroke="#fff" stroke-width="2"/><path d="M9.5 16h21M9.5 24h21" stroke="#fff" stroke-width="1.8"/><circle cx="31" cy="9" r="3.2" fill="#fff"/></svg>'
BRAND='<span class="brand">'+LOGO+'<span><b>GWB</b><small>Greater World Business</small></span></span>'
FOOTER='<footer>'+BRAND+'<p>Your one-stop shop for small business tools</p><nav aria-label="Site links"><ul class="flinks"><li><a href="HREFBASEindex.html#tools">All tools</a></li><li><a href="HREFBASEabout/">About</a></li><li><a href="HREFBASEcontact/">Contact</a></li><li><a href="HREFBASEprivacy/">Privacy Policy</a></li><li><a href="HREFBASEterms/">Terms</a></li><li><a href="https://buy.stripe.com/7sY6oGgJR5Vh3MabNQ3F600" rel="noopener">Tip GWB</a></li></ul></nav><p>Contact: <a href="mailto:ozor.inc@gmail.com">ozor.inc@gmail.com</a> · &copy; 2026 GWB: Greater World Business</p></footer>'
PRIV=("Are my files or text uploaded anywhere?","No. This tool runs entirely in your browser using JavaScript. Nothing you enter or open is sent to our servers or stored by us.")
FAQ={
'invoice':(["Enter your business details and your client's details.","Add line items with quantity and price, and set a tax rate if needed.","Click Download PDF and choose “Save as PDF” in the print dialog."],[("Is the invoice generator really free?","Yes. There are no watermarks, limits or accounts. You can create as many invoices and receipts as you like."),("Can I make a receipt instead of an invoice?","Yes. Switch the document type to Receipt; the layout and totals stay the same."),("How do I save the invoice as a PDF?","Click Download PDF. Your browser's print dialog opens; pick “Save as PDF” as the destination."),PRIV]),
'resume':(["Paste a plain job duty, such as “handled customer emails”.","Choose a verb style and add a number and a result if you have them.","Copy the bullet that fits best and adjust the details."],[("What makes a strong resume bullet?","A strong bullet starts with an action verb, says what you did, and shows a measurable result, such as volume, money saved or a percentage improvement."),("Should I include numbers if I'm not sure of them?","Use honest estimates you can explain in an interview, such as “about 200 tickets a week”. Never invent results."),("How many bullets should each job have?","Three to five focused bullets per role is typical. Put your most impressive result first."),PRIV]),
'meeting-cost':(["Enter the number of attendees and their average hourly rate, or an annual salary.","Set the planned length to see the estimated cost.","Press Start during the meeting to watch the live cost."],[("How is the meeting cost calculated?","Attendees × average hourly rate × meeting length. An annual salary is converted using 2,080 working hours per year."),("Does it include overhead like benefits?","No. If you want a fuller picture, raise the hourly rate by about 25–40% to approximate benefits and overhead."),("Why show the yearly cost?","A weekly meeting runs about 52 times a year, so small costs add up. The yearly figure helps decide whether a meeting is worth it."),PRIV]),
'qr-bio':(["Type the link or text you want the QR code to open.","Download the QR code as a PNG for print or screens.","Optionally build a link-in-bio page and download bio.html to host anywhere."],[("Do these QR codes expire?","No. The QR code encodes your link directly, so it works as long as the link itself works. There is no redirect service in between."),("How do I host the link-in-bio page?","Upload bio.html to any static host, such as GitHub Pages, Netlify or your own website, and link to it from your social profiles."),("What size should I print a QR code?","At least 2 × 2 cm (about 0.8 inches) for close scanning. Go larger for posters, and always test with a phone first."),PRIV]),
'policy':(["Enter your business name, website, contact email and location.","Pick the policy type: privacy, terms or refund.","Copy or download the draft and review it before publishing."],[("Are these policies legally binding?","They are general templates to help you get started, not legal advice. Laws vary by country and industry, so have a qualified lawyer review them."),("Do I need a privacy policy?","Most websites that collect any personal data, use analytics or show ads need one, and many platforms and payment providers require it."),("Can I edit the generated text?","Yes. Copy it into your editor and adjust it to match exactly how your business works."),PRIV]),
'audio':(["Open an audio file from your device.","Drag the start and end sliders, and add a fade in or out.","Preview, then export as MP3 or WAV."],[("How long should a ringtone be?","Most phones work well with 20 to 30 seconds. iPhone ringtones are limited to about 30 seconds."),("MP3 or WAV: which should I choose?","MP3 is much smaller and works almost everywhere. WAV is lossless and larger, which is useful for further editing."),("Can I use any song?","Only use audio you own or have the rights to use. This tool works with files already on your device and never downloads from other sites."),PRIV]),
'image-compress':(["Choose an image from your device.","Set the maximum width and quality, and pick JPG, WEBP or PNG.","Download the compressed image and compare the size savings."],[("What quality setting should I use?","Around 70–80% usually looks identical to the original while cutting file size dramatically. Lower it further for thumbnails."),("What size is best for websites and social media?","About 1600 px wide for website images, 1080 px for Instagram posts, and 1200 px for email attachments."),("Why is my PNG not getting smaller?","PNG is lossless, so photos stay large. Switch to JPG or WEBP for photos; keep PNG for logos and screenshots with sharp edges."),PRIV]),
'image-convert':(["Select one or more images.","Pick the target format: PNG, JPG or WEBP.","Click Convert and download each file."],[("Which format should I choose?","JPG for photos, PNG when you need transparency or crisp edges, and WEBP for the smallest files on modern websites."),("What happens to transparent areas in JPG?","JPG does not support transparency, so transparent areas are filled with the background color you choose."),("Can I convert HEIC photos from my iPhone?","Only if your browser can open HEIC files. Safari usually can; other browsers may not. On iPhone you can also set the camera to “Most Compatible” to save JPGs."),PRIV]),
'pdf-tools':(["Choose a task: merge, extract/split, or images to PDF.","Select your files (PDFs or images).","Click the button and download the result."],[("Is there a file size or page limit?","There is no fixed limit. Very large files depend on your device's memory, since everything runs locally."),("How do I extract specific pages?","Choose “Extract or split pages”, then type pages like “1-3, 5”. Tick “Save each page” to get one PDF per page."),("Can it open password-protected PDFs?","Encrypted PDFs may fail or produce blank pages. Remove the password in your PDF reader first if you own the document."),PRIV]),
'word-counter':(["Paste or type your text into the box.","Read the live counts for words, characters, sentences and paragraphs.","Check reading time and top keywords."],[("How is reading time calculated?","Reading time uses an average of about 238 words per minute; speaking time uses about 150 words per minute."),("Does it count spaces as characters?","Both counts are shown: characters with spaces and characters without spaces."),("How long should a meta description be?","About 150–160 characters is a common guideline so search engines don't cut it off."),PRIV]),
'password':(["Choose a length (16 or more is recommended).","Pick which character types to include.","Copy one of the generated passwords."],[("How random are these passwords?","They use your browser's cryptographically secure random number generator (crypto.getRandomValues) with unbiased selection."),("How long should a password be?","At least 12–16 characters. Longer is better, especially for email, banking and password-manager master passwords."),("Should I reuse a strong password?","No. Use a unique password for every account and store them in a password manager."),PRIV]),
'biz-calc':(["Pick the calculator you need: margin, sales tax, loan or break-even.","Type your numbers; results update instantly.","Use the results to set prices or plan financing."],[("What is the difference between margin and markup?","Margin is profit as a percentage of the selling price. Markup is profit as a percentage of cost. A 50% markup equals a 33.3% margin."),("How is the loan payment calculated?","It uses the standard amortization formula with monthly compounding: payment = P × r ÷ (1 − (1 + r)^−n)."),("What does break-even mean?","It is the number of units you must sell so that revenue covers fixed costs plus variable costs, with zero profit."),PRIV]),
'business-name':(["Enter one or two keywords that describe your business.","Choose a style: modern, classic, playful or tech.","Generate ideas and shortlist your favorites."],[("Can I use any name I find here?","Names are suggestions only. Check trademark databases, your local business registry and domain availability before using one."),("How do I choose a good business name?","Keep it short, easy to spell and say, and relevant to what you offer. Say it out loud and check it on social platforms."),("Why do I get different names each time?","The generator combines your keywords with style-based words randomly, so each click gives fresh ideas."),PRIV]),
'email-signature':(["Fill in your name, title, company and contact details.","Pick an accent color.","Copy the signature and paste it into your email settings."],[("How do I add it to Gmail?","In Gmail, open Settings → See all settings → Signature, create a new signature, and paste."),("How do I add it to Outlook?","In Outlook, go to Settings → Mail → Compose and reply (or Signatures), create a signature, and paste."),("Why does my signature look different in some apps?","Email apps render HTML differently. This generator uses simple table-based inline styles for the best compatibility."),PRIV]),
'color-palette':(["Choose a base color, such as your logo color.","Pick a harmony rule or click Random.","Click swatches to copy hex codes, or copy the CSS variables."],[("Which harmony should I choose?","Analogous palettes feel calm and cohesive; complementary palettes create contrast; triadic palettes feel vibrant and balanced."),("How do I keep text readable on these colors?","Each swatch label switches between dark and light text for legibility. For body text, aim for a contrast ratio of at least 4.5:1."),("Can I use these colors commercially?","Yes. Colors are not owned; use the palette anywhere."),PRIV]),
'video-to-mp3':(["Open a video file from your device (MP4, WebM or MOV).","Choose MP3 or WAV and a quality.","Export and download the audio file."],[("Which video formats work?","Any format your browser can decode. MP4 (AAC audio) and WebM work in most browsers; some MOV or HEVC files may not."),("Can I extract audio from YouTube links?","No. This tool only works with video files already on your device that you own or have the rights to use."),("What MP3 quality should I pick?","192 kbps is a good balance. Use 320 kbps for music where quality matters, or 128 kbps for speech."),PRIV])}

