{k:'word-counter',s:'word,words,count,counter,character,characters,letters,essay,length,limit,tweet,reading time,article,blog,how many words',say:'count words or characters',tips:['Paste text to see words, characters and reading time instantly.','Meta descriptions work best under about 155 characters.','Top keywords show which words you repeat most.'],rel:['resume','policy']},
